   "resumen": "Los pacientes afiliados que se desplacen a Lima, Callao, Lambayeque, Cajamarca, Cusco y Ucayali podrán recibir atención en los establecimientos de salud durante las actividades programadas del sumo pontífice.",
   "fuente": "RPP",
